// Combine webhook data with pricing data
const formData = $('When Project Proposal Received').item.json.body;
const allPricing = $('Read Pricing Data from Sheets').all();

// Clean and structure the pricing data
const pricingMap = {};
allPricing.forEach(item => {
  const title = item.json.Title?.toLowerCase() || '';
  const category = item.json.Category?.toLowerCase() || '';
  pricingMap[title] = {
    ...item.json,
    searchTerms: [title, category].filter(Boolean)
  };
});

// Parse project description to identify potential services
const projectDesc = (formData['Project Description'] || '').toLowerCase();
const keywords = [
  'model', 'training', 'policy', 'guidelines', 'standards', 
  'compliance', 'workflow', 'automation', 'implementation',
  'consulting', 'assessment', 'strategy', 'development',
  'website', 'governance', 'security', 'ediscovery'
];

const identifiedKeywords = keywords.filter(kw => projectDesc.includes(kw));

// Extract selected services from form
const selectedServices = formData['Services'] || [];

return [{
  json: {
    formData,
    pricingData: pricingMap,
    pricingList: allPricing.map(p => p.json),
    projectKeywords: identifiedKeywords,
    selectedServices: selectedServices,
    requestDate: new Date().toISOString(),
    metadata: {
      totalPricingItems: Object.keys(pricingMap).length,
      hasBudget: !!(formData['Estimated Budget Range']),
      timeline: formData['Desired Timeline'] || 'Not specified',
      pricingLevel: formData['Pricing Level'] || 'Standard',
      hasSpecialRequirements: !!(formData['Special Requirements']),
      currentSystems: formData['Current Systems/Tools'] || 'Not specified'
    }
  }
}];

// Prepare search queries for missing services
const data = $('Process AI Analysis').item.json;
const missingServices = data.missingServices || [];

// Create individual search queries for each missing service
const queries = missingServices.map(service => ({
  json: {
    serviceName: service.serviceName,
    searchQuery: service.searchQuery || 
      `${service.serviceName} pricing cost legal technology consulting ${new Date().getFullYear()}`,
    originalData: data
  }
}));

// Return all queries for batch processing
return queries.length > 0 ? queries : [{
  json: {
    serviceName: 'None',
    searchQuery: '',
    originalData: data
  }
}];

// Parse web search results and extract pricing
const searchResult = $('Fetch Market Prices').item.json;
const queryData = $('Prepare Market Search Queries').item.json;

let estimatedPrice = 150; // Default hourly rate
let priceRange = { low: 100, high: 200 };
let confidence = 'Low';

// Extract pricing from search results
if (searchResult.organic_results) {
  searchResult.organic_results.forEach(result => {
    const snippet = (result.snippet || '').toLowerCase();
    // Look for price patterns
    const priceMatches = snippet.match(/\$(\d+)(?:\s*-\s*\$?(\d+))?(?:\s*(?:per|\/)\s*(hour|day|project))?/gi);
    if (priceMatches && priceMatches.length > 0) {
      const match = priceMatches[0];
      const numbers = match.match(/\d+/g);
      if (numbers) {
        priceRange.low = Math.min(priceRange.low, parseInt(numbers[0]));
        if (numbers[1]) {
          priceRange.high = Math.max(priceRange.high, parseInt(numbers[1]));
        }
        confidence = 'Medium';
      }
    }
  });
  estimatedPrice = Math.round((priceRange.low + priceRange.high) / 2);
}

return [{
  json: {
    ...queryData.originalData,
    webPricing: {
      serviceName: queryData.serviceName,
      estimatedPrice,
      priceRange,
      confidence,
      source: 'Market Research'
    }
  }
}];

// Parse AI analysis and prepare for routing
const analysisResult = $('Project Analysis Agent').item.json;
let analysis = {};

// Handle different response formats
try {
  if (typeof analysisResult === 'object' && !analysisResult.output) {
    // Already parsed JSON
    analysis = analysisResult;
  } else if (typeof analysisResult.output === 'string') {
    // Try to extract JSON from the output string
    let outputStr = analysisResult.output;

    // Remove any non-JSON prefix text
    const jsonMatch = outputStr.match(/\{[\s\S]*\}$/);
    if (jsonMatch) {
      outputStr = jsonMatch[0];
    }

    // Clean common issues
    outputStr = outputStr
      .replace(/^[^{]*/, '')  // Remove everything before first {
      .replace(/[^}]*$/, '')  // Remove everything after last }
      .replace(/```json\n?/gi, '') // Remove markdown code blocks
      .replace(/```\n?/gi, '')
      .trim();

    analysis = JSON.parse(outputStr);
  } else if (typeof analysisResult.output === 'object') {
    analysis = analysisResult.output;
  } else {
    // Fallback: create a basic structure
    console.error('Could not parse AI output, using fallback structure');
    analysis = {
      projectAnalysis: {
        summary: "Project analysis pending",
        complexity: "Medium",
        estimatedHours: 40,
        phases: [
          {
            name: "Discovery & Planning",
            description: "Initial assessment and planning",
            deliverables: ["Requirements document", "Project plan"],
            estimatedHours: 10,
            duration: "1 week"
          },
          {
            name: "Implementation",
            description: "Main implementation phase",
            deliverables: ["Configured solution", "Documentation"],
            estimatedHours: 20,
            duration: "2 weeks"
          },
          {
            name: "Training & Rollout",
            description: "Training and deployment",
            deliverables: ["Training materials", "Support documentation"],
            estimatedHours: 10,
            duration: "1 week"
          }
        ]
      },
      requiredServices: [],
      missingServices: [],
      riskFactors: [],
      recommendations: []
    };
  }
} catch (error) {
  console.error('Error parsing AI output:', error);
  // Use fallback structure
  analysis = {
    projectAnalysis: {
      summary: "Project requires detailed analysis",
      complexity: "Medium",
      estimatedHours: 40,
      phases: []
    },
    requiredServices: [],
    missingServices: [],
    riskFactors: [],
    recommendations: []
  };
}

const formData = $('Combine Proposal with Pricing').item.json.formData;
const pricingData = $('Combine Proposal with Pricing').item.json.pricingData;

// Ensure required fields exist
analysis.requiredServices = analysis.requiredServices || [];
analysis.missingServices = analysis.missingServices || [];
analysis.projectAnalysis = analysis.projectAnalysis || {};

// Check if we have missing services
const hasMissingServices = analysis.missingServices && analysis.missingServices.length > 0;

return [{
  json: {
    analysis,
    formData,
    pricingData,
    hasMissingServices,
    missingServices: analysis.missingServices,
    requiredServices: analysis.requiredServices,
    projectAnalysis: analysis.projectAnalysis
  }
}];

// Process data when no web search is needed
const data = $('Process AI Analysis').item.json;

return [{
  json: {
    ...data,
    webPricing: null
  }
}];

// Get data from either path (with or without search)
const inputData = $input.item.json;
const analysis = inputData.analysis;
const formData = inputData.formData;
const pricingData = inputData.pricingData;
const webPricing = inputData.webPricing;

// Calculate total project cost and build breakdown
let totalCost = 0;
let costBreakdown = [];

// Process each required service
(analysis.requiredServices || []).forEach(service => {
  let price = 0;
  let unit = 'hour';
  let source = 'Estimated';

  // Try to find in pricing data using fuzzy matching
  const pricingKey = Object.keys(pricingData).find(key => {
    const serviceNameLower = service.serviceName.toLowerCase();
    return key.includes(serviceNameLower) || 
           serviceNameLower.includes(key) ||
           // Check for common substitutions
           (serviceNameLower.includes('copilot') && key.includes('training')) ||
           (serviceNameLower.includes('policy') && key.includes('governance')) ||
           (serviceNameLower.includes('model') && key.includes('ai'));
  });

  if (pricingKey) {
    const pricing = pricingData[pricingKey];
    price = parseFloat(pricing.Retail) || 0;
    unit = pricing.Unit || 'hour';
    source = 'Standard Pricing';
  } else if (webPricing && service.serviceName === webPricing.serviceName) {
    price = webPricing.estimatedPrice;
    source = `Market Research (${webPricing.confidence} confidence)`;
  } else {
    // Default pricing based on service type
    if (service.serviceName.toLowerCase().includes('training')) {
      price = 175;
    } else if (service.serviceName.toLowerCase().includes('consulting')) {
      price = 200;
    } else if (service.serviceName.toLowerCase().includes('development')) {
      price = 150;
    } else {
      price = 150;
    }
    source = 'Estimated';
  }

  const quantity = service.quantity || 1;
  const lineTotal = price * quantity;
  totalCost += lineTotal;

  costBreakdown.push({
    service: service.serviceName,
    description: service.justification || '',
    unitPrice: price,
    unit: unit,
    quantity: quantity,
    total: lineTotal,
    source: source,
    phase: service.phase || 'Implementation'
  });
});

// Parse budget range
let budgetMin = 0;
let budgetMax = 0;
if (formData['Estimated Budget Range']) {
  const budgetMatch = formData['Estimated Budget Range'].match(/\$?([\d,]+)\s*-\s*\$?([\d,]+)/);
  if (budgetMatch) {
    budgetMin = parseInt(budgetMatch[1].replace(/,/g, ''));
    budgetMax = parseInt(budgetMatch[2].replace(/,/g, ''));
  }
}

// Create timeline/Gantt data
const phases = analysis.projectAnalysis?.phases || [];
let ganttData = [];
let startDate = new Date();

phases.forEach((phase, index) => {
  const phaseStart = new Date(startDate);
  const weeks = parseInt(phase.duration) || 4;
  const phaseEnd = new Date(phaseStart);
  phaseEnd.setDate(phaseEnd.getDate() + (weeks * 7));

  // Calculate phase cost
  const phaseCost = costBreakdown
    .filter(item => item.phase === phase.name)
    .reduce((sum, item) => sum + item.total, 0);

  ganttData.push({
    phase: phase.name,
    start: phaseStart.toISOString().split('T')[0],
    end: phaseEnd.toISOString().split('T')[0],
    deliverables: phase.deliverables,
    hours: phase.estimatedHours,
    cost: phaseCost,
    weeks: weeks
  });

  startDate = new Date(phaseEnd);
  startDate.setDate(startDate.getDate() + 7); // 1 week buffer
});

// Add any unassigned costs to a general phase
const unassignedCost = totalCost - ganttData.reduce((sum, phase) => sum + phase.cost, 0);
if (unassignedCost > 0 && ganttData.length > 0) {
  ganttData[0].cost += unassignedCost;
}

return [{
  json: {
    clientInfo: {
      name: formData['prospectName'] || 'Client',
      requestor: formData['requestorName'] || 'Contact',
      email: formData['requestorEmail'] || '',
      location: formData['Current Systems/Tools'] || '',
      date: formData['date'] || new Date().toISOString().split('T')[0],
      services: formData['services'] || '',
      discountLevel: formData['discountLevel'] || 'Standard'
    },
    projectOverview: {
      description: formData['Project Description'],
      complexity: analysis.projectAnalysis?.complexity || 'Medium',
      totalHours: analysis.projectAnalysis?.estimatedHours || 0,
      timeline: formData['Desired Timeline'],
      summary: analysis.projectAnalysis?.summary || ''
    },
    financials: {
      costBreakdown,
      totalCost,
      budgetMin,
      budgetMax,
      withinBudget: totalCost <= budgetMax,
      budgetUtilization: budgetMax > 0 ? ((totalCost / budgetMax) * 100).toFixed(1) : 0
    },
    timeline: ganttData,
    phases: analysis.projectAnalysis?.phases || [],
    risks: analysis.riskFactors || [],
    recommendations: analysis.recommendations || [],
    proposalDate: new Date().toISOString().split('T')[0]
  }
}];

/**
 * legalGPTs Proposal & Email Stylizer
 * Branding: Navy (#002657), Blue (#0021a5), Orange (#fa4616)
 */

// Safely extract input data
const aiOutput = $('Proposal HTML Creator Agent').item.json;
const proposalData = $('Compile Proposal Data').item.json;
const logoUrl = 'https://legalgpts.com/wp-content/uploads/2026/02/lg_orangeblue_clear.png';

let proposalOutput = '';
if (aiOutput) {
  proposalOutput = aiOutput.output || aiOutput.text || aiOutput.data || '';
}

if (typeof proposalOutput !== 'string') {
  proposalOutput = JSON.stringify(proposalOutput) || '';
}

// Clean HTML output
let rawBody = proposalOutput.replace(/^```html\n?/gi, '').replace(/\n?```$/gi, '').trim();

// 1. GENERATE BRANDED PDF HTML
const htmlContent = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Project Proposal - ${proposalData.clientInfo?.name || "Client"}</title>
  <style>
    :root {
      --navy: #002657;
      --blue: #0021a5;
      --orange: #fa4616;
      --charcoal: #343741;
      --light-bg: #f8f9fa;
    }
    @page { size: letter; margin: 20mm; }
    body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; line-height: 1.6; color: var(--charcoal); margin: 0; padding: 0; }

    .header { 
      display: flex; 
      justify-content: space-between; 
      align-items: center; 
      border-bottom: 4px solid var(--orange); 
      padding-bottom: 20px; 
      margin-bottom: 40px; 
    }
    .logo { height: 60px; width: auto; }
    .header-meta { text-align: right; color: var(--navy); }

    h1 { color: var(--navy); font-size: 28pt; margin: 0; text-transform: uppercase; letter-spacing: -1px; }
    h2 { color: var(--navy); border-left: 6px solid var(--blue); padding-left: 15px; margin-top: 35px; font-size: 18pt; }
    h3 { color: var(--blue); margin-top: 25px; font-size: 14pt; }

    table { width: 100%; border-collapse: collapse; margin: 25px 0; }
    th { background: var(--navy); color: white; padding: 12px; text-align: left; text-transform: uppercase; font-size: 10pt; }
    td { padding: 12px; border-bottom: 1px solid #eee; font-size: 10pt; }

    .highlight, .success { padding: 20px; border-radius: 6px; margin: 25px 0; border-left: 5px solid; }
    .highlight { background: #fff5f2; border-left-color: var(--orange); }
    .success { background: #f0f4ff; border-left-color: var(--blue); }

    .footer { text-align: center; font-size: 9pt; color: #999; margin-top: 50px; border-top: 1px solid #eee; padding-top: 20px; }
  </style>
</head>
<body>
  <div class="header">
    <img src="${logoUrl}" class="logo" alt="legalGPTs">
    <div class="header-meta">
      <strong>Proposal ID:</strong> PRO-${new Date().getTime().toString().slice(-6)}<br>
      <strong>Date:</strong> ${new Date().toLocaleDateString()}
    </div>
  </div>
  <h1>Project Proposal</h1>
  <p style="color: var(--blue); font-weight: bold; font-size: 14pt; margin-top: -10px;">
    Prepared for ${proposalData.clientInfo?.name || "Client"}
  </p>
  ${rawBody}
  <div class="footer">
    legalGPTs | Excellence in Legal Technology Consulting | legalgpts.com
  </div>
</body>
</html>`;

// 2. GENERATE BRANDED EMAIL HTML
const date = new Date().toISOString().split('T')[0];
const emailBodyHTML = `
<body style="margin: 0; padding: 0; font-family: Arial, sans-serif; background-color: #f4f7f9;">
  <table width="100%" bgcolor="#f4f7f9" cellpadding="0" cellspacing="0" style="padding: 40px 0;">
    <tr>
      <td align="center">
        <table width="600" bgcolor="#ffffff" style="border-radius: 8px; border-top: 6px solid #fa4616; box-shadow: 0 4px 10px rgba(0,0,0,0.1);">
          <tr>
            <td style="padding: 30px; text-align: center; background-color: #002657;">
              <img src="${logoUrl}" width="180" alt="legalGPTs">
            </td>
          </tr>
          <tr>
            <td style="padding: 40px;">
              <h2 style="color: #002657; margin-top: 0;">Proposal Ready for Review</h2>
              <p style="color: #343741; font-size: 16px;">Dear ${proposalData.clientInfo?.requestor || "Contact"},</p>
              <p style="color: #343741; line-height: 1.6;">We have completed the comprehensive proposal for <strong>${proposalData.clientInfo?.name || "Client"}</strong>.</p>

              <div style="background-color: #f0f4ff; border-left: 4px solid #0021a5; padding: 20px; margin: 25px 0;">
                <p style="margin: 0; color: #002657; font-weight: bold;">Estimated Investment:</p>
                <p style="font-size: 24px; color: #0021a5; margin: 5px 0;">$${(proposalData.financials?.totalCost || 0).toLocaleString()}</p>
              </div>

              <p style="color: #343741;">Please find the full project roadmap and success metrics attached in both PDF and Word (DOCX) formats.</p>

              <table width="100%" cellpadding="0" cellspacing="0" style="margin-top: 30px;">
                <tr>
                  <td align="center">
                    <a href="mailto:user@example.com" style="background-color: #fa4616; color: #ffffff; padding: 15px 30px; text-decoration: none; border-radius: 4px; font-weight: bold;">Schedule a Call</a>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>`;

// 3. PREPARE OUTPUT & BINARY
const clientName = (proposalData.clientInfo?.name || "Client").replace(/[^a-zA-Z0-9]/g, '-');
const fileNameBase = `${clientName}-Proposal-${date}`;
const fileName = `${fileNameBase}.pdf`;
const fileNameDocx = `${fileNameBase}.docx`;
const htmlBuffer = Buffer.from(htmlContent, 'utf-8');

return [{
  json: {
    htmlContent,
    fileName,
    fileNameBase,
    fileNameDocx,
    clientDisplayName: proposalData.clientInfo?.name || 'Client',
    emailBody: emailBodyHTML,
    recipients: ['user@example.com', proposalData.clientInfo?.email].filter(Boolean).join(';')
  },
  binary: {
    data: {
      data: htmlBuffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html'
    }
  }
}];

